from threetears.evals import Eval

from split import Bill, split

def share(case):
    """What each diner at the table is charged."""
    return {"charged": split(Bill.from_row(case))}


def as_charged(case, out):
    """Every diner is charged what the terminals charged."""
    return out["charged"] == case["charged"]

tables = Eval("data/terminal.jsonl", runner=share, grader=[as_charged], k=1)
